DROP VIEW "public"."task_assignment_detail";--> statement-breakpoint
CREATE VIEW "public"."task_assignment_detail" AS (select "task_assignment"."id" as "assignment_id", "task"."id" as "task_id", "user"."id" as "user_id", "task_assignment"."status" as "status", "task_assignment"."comment" as "comment", "task_assignment"."start_date" as "start_date", "task_assignment"."end_date" as "end_date", "task_assignment"."created_at" as "created_at", "task"."name" as "task_name", "task"."description" as "task_description", "task"."priority" as "task_priority", "task"."recurrence" as "task_recurrence", "task"."project_id" as "project_id", "user"."name" as "user_name", "user"."email" as "user_email", "user"."image" as "user_image" from "task_assignment" inner join "task" on "task_assignment"."task_id" = "task"."id" inner join "user" on "task_assignment"."user_id" = "user"."id");